147	center	{"blocks":[{"key":"egl6","text":"Měníme způsob, jakým firmy řídí své finance.","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":44,"style":"color-#becd00"}],"entityRanges":[],"data":{}}],"entityMap":{}}	\N	t	t	{"blocks":[{"key":"1t2go","text":"Direct","type":"header-one","depth":0,"inlineStyleRanges":[{"offset":0,"length":6,"style":"color-#000"}],"entityRanges":[],"data":{}},{"key":"9v1c6","text":"Fidoo","type":"header-one","depth":0,"inlineStyleRanges":[{"offset":0,"length":5,"style":"color-#000"}],"entityRanges":[],"data":{}}],"entityMap":{}}	1:1
157	center	{"blocks":[{"key":"cre6t","text":"Direct financing je společnost s ručením omezeným vzniklá v listopadu 2021. Direct financing byla založena za účelem vydávání dluhopisů a následného poskytování vnitroskupinového financování Direct family.","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}	\N	t	t	{"blocks":[{"key":"bfm7a","text":"Vítejte v","type":"header-one","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}},{"key":"7at3b","text":"Direct financing ","type":"header-one","depth":0,"inlineStyleRanges":[{"offset":0,"length":17,"style":"color-#000"}],"entityRanges":[],"data":{}}],"entityMap":{}}	1:1
239	center	{"blocks":[{"key":"4la5v","text":"Jsme u událostí, které významně ovlivňují životy lidí. Snažíme se okamžitě pomoct tam, kde je to nejvíce potřeba. Pokud můžeme pomoct, pomáháme.","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}	\N	t	t	{"blocks":[{"key":"440vc","text":"Co děláme","type":"header-one","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}	1:1
