269	center	{"blocks":[{"key":"egl6","text":"Držíme se hesla, ve zdravém těle zdravý duch. A proto rekreačnímu sportu pomáháme vracet jeho smysl a dětem radost z něj. ","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":19,"style":"color-#000"},{"offset":44,"length":78,"style":"color-#000"},{"offset":19,"length":25,"style":"color-#becd00"}],"entityRanges":[],"data":{}}],"entityMap":{}}	\N	t	t	{"blocks":[{"key":"1t2go","text":"Pohybem pro radost","type":"header-one","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}	1:1
229	center	{"blocks":[{"key":"d069v","text":"V Directu jsme za sebou vždy chtěli vidět výsledky, ale současně nám šlo o nezávislost, svobodu, toleranci, osobní odpovědnost a vzájemnost. Business pro nás nikdy nebyl cílem, ale pouze nástrojem, jak měnit svět kolem sebe k lepšímu. Proto v roce 2010 vznikla nadace.","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":75,"length":65,"style":"color-#becd00"}],"entityRanges":[],"data":{}}],"entityMap":{}}	\N	f	f	{"blocks":[{"key":"36red","text":"Proč vznikla Direct nadace","type":"header-one","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}	1:1
236	center	{"blocks":[{"key":"egl6","text":"Věříme, že vzdělávání mladých lidí a vytváření příležitostí, je investice do budoucnosti, která pomůže zlepšovat svět, ve kterém žijeme.","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":63,"style":"color-#000"},{"offset":88,"length":1,"style":"color-#000"},{"offset":90,"length":46,"style":"color-#000"},{"offset":63,"length":25,"style":"color-#becd00"},{"offset":89,"length":1,"style":"color-#808080"}],"entityRanges":[],"data":{}}],"entityMap":{}}	\N	t	t	{"blocks":[{"key":"1t2go","text":"Odemykání potenciálu","type":"header-one","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}	1:1
