196	left	{"blocks":[{"key":"5c0d6","text":"Pomůžeme vám, když vaše auto nechce jet dál. Ať už kvůli nehodě nebo poruše. Zařídíme odtah i mechanika.","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":51,"length":24,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"bm4gq","text":"","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}	#card	f	f	{"blocks":[{"key":"1qvq7","text":"Asistenční služby","type":"header-one","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}	202.22222222
344	left	{"blocks":[{"key":"6s8sr","text":"Direct pojišťovna to czeska firma ubezpieczeniowa, od 10-ciu lat oferująca nowoczesne i przejrzyste rozwiązania dla klientów indywidualnych oraz firm. Specjalizuje się w ubezpieczeniach komunikacyjnych, majątkowych i podróżnych, kładąc nacisk na prostotę obsługi oraz sprawną likwidację szkód.","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":17,"style":"BOLD"},{"offset":54,"length":10,"style":"BOLD"}],"entityRanges":[],"data":{}}],"entityMap":{}}	\N	t	f	{"blocks":[{"key":"at02a","text":"Witamy w ","type":"header-one","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}},{"key":"1iri","text":"Direct ubezpieczenia","type":"header-one","depth":0,"inlineStyleRanges":[{"offset":0,"length":20,"style":"color-#becd00"}],"entityRanges":[],"data":{}}],"entityMap":{}}	100
