772	Oznámení o založení základního prospektu dluhopisového programu	{"blocks":[{"key":"81h7n","text":"Direct Financing s.r.o. oznamuje, že dne 25. 9. 2023 rozhodl statutární orgán společnosti a jediný společník společnosti o založení Základního prospektu dluhopisového programu společnosti.","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}},{"key":"mins","text":"Rozhodnutí statutárního orgánu a jediného společníka Společnosti je možné nalézt zde.","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[{"offset":81,"length":3,"key":0}],"data":{}}],"entityMap":{"0":{"type":"LINK","mutability":"MUTABLE","data":{"url":"https://cdn-direct.s3.eu-west-1.amazonaws.com/230925_rozhodnuti_VH_Bo_D_zalozeni_zakladniho_prospektu_0623e53d0a.pdf?updated_at=2023-09-25T13:10:18.943Z","targetOption":"_blank"}}}}
703	Archív pojistné podmínky	{"blocks":[{"key":"3m01q","text":"Pojistné podmínky pojištění odpovědnosti platné od 18.10.2018 - 25.1.2019 (ZIP) ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[{"offset":0,"length":79,"key":0}],"data":{}},{"key":"9ua3g","text":"Pojistné podmínky pojištění odpovědnosti platné od 1.3.2018 - 18.10.2018 (ZIP) ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[{"offset":0,"length":78,"key":1}],"data":{}},{"key":"3ekh7","text":"Pojistné podmínky pojištění odpovědnosti platné od 15.10.2017 - 10/2017 (ZIP) ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[{"offset":0,"length":77,"key":2}],"data":{}},{"key":"1hcpf","text":"Pojistné podmínky platné od 1.2.2016 do 15.10.2017 - 02/2016 (ZIP) ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[{"offset":0,"length":66,"key":3}],"data":{}},{"key":"9b1ko","text":"Archiv dokumentů pojištění (ZIP)   ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[{"offset":0,"length":32,"key":4}],"data":{}}],"entityMap":{"0":{"type":"LINK","mutability":"MUTABLE","data":{"url":"/download/insurance/people/liability/archive/Pojistne_podminky_platne_od_18-10-2018_do_25-01-2019.zip","targetOption":"_blank"}},"1":{"type":"LINK","mutability":"MUTABLE","data":{"url":"/download/insurance/people/liability/archive/Pojistne_podminky_platne_od_1-3-2018_do_18-10-2018.zip","targetOption":"_blank"}},"2":{"type":"LINK","mutability":"MUTABLE","data":{"url":"/download/insurance/people/liability/archive/Odpovednost_10-2017.zip","targetOption":"_blank"}},"3":{"type":"LINK","mutability":"MUTABLE","data":{"url":"/download/insurance/people/liability/archive/Odpovednost_02-2016.zip","targetOption":"_blank"}},"4":{"type":"LINK","mutability":"MUTABLE","data":{"url":"/download/insurance/people/archiv_dokumentu_k_pojisteni_pro_lidi.zip","targetOption":"_blank"}}}}
