180	Pojištění odpovědnosti	{"blocks":[{"key":"ercqi","text":"Takzvané pojištění na blbost se vztahuje na škody, které způsobíte ostatním při běžných činnostech nebo na škody způsobené nemovitostí, například když spadne střešní taška na auto před domem nebo při vytopení bytu souseda. ","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":223,"style":"color-#808080"},{"offset":9,"length":19,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"8cn3h","text":"","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}},{"key":"4rlqp","text":"Automaticky jsou pojištění všichni lidé, kteří žijí v pojištěné nemovitosti. A nemusí tam mít ani trvalé bydliště.","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":114,"style":"color-#808080"},{"offset":27,"length":48,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"50uvh","text":"","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}},{"key":"3fcg","text":"Pojištění odpovědnosti platí na území celé Evropy. Lze rozšířit o:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":66,"style":"color-#808080"},{"offset":29,"length":20,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"3gkka","text":"- odpovědnost za zvíře, ","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":24,"style":"color-#808080"}],"entityRanges":[],"data":{}},{"key":"4ko16","text":"- odpovědnost na věcech pronajatých, ","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":37,"style":"color-#808080"}],"entityRanges":[],"data":{}},{"key":"9k2jt","text":"- odpovědnost na drobné elektronice,","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":36,"style":"color-#808080"}],"entityRanges":[],"data":{}},{"key":"p3tt","text":"- odpovědnost z vlastnictví všech vašich nemovitostí.","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":53,"style":"color-#808080"}],"entityRanges":[],"data":{}},{"key"