80	{"blocks":[{"key":"8l60o","text":"Jak jsme to vyřešili: ","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":22,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"8dekt","text":"Všechny tyto požadavky vyřešil náš nový portál pro obchodní partnery Direct connection.","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
