90	{"blocks":[{"key":"14pk3","text":"Co se vám nelíbilo:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":19,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"90qe6","text":"\\"Chybí mi havarijní pojištění vozidel jen na léto.\\"","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
57	{"blocks":[{"key":"47imq","text":"Co se vám nelíbilo:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":19,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"2eafk","text":"„Odejít k vám z jiné pojišťovny je složité.\\"","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
49	{"blocks":[{"key":"97m3t","text":"Co se vám nelíbilo:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":19,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"58mpb","text":"„Při sjednání pojištění auta jsem nemohl nalézt možnost nastavit jinou frekvenci než roční.\\"","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
52	{"blocks":[{"key":"e821o","text":"Co se vám nelíbilo:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":19,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"9n2jt","text":"„Při sjednání pojištění nemohu nalézt konkrétní informace ohledně toho, co je zahrnuto v nákladech na asistenci a co není.\\"","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
53	{"blocks":[{"key":"40nf4","text":"Co se vám nelíbilo:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":19,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"4b4f6","text":"„Vaše webové nahlášení škody je strašně složité a nepoužitelné. Příliš mnoho políček k vyplnění, některá dokonce nefunkční, nejasný text, z kterého nevím, co mám dělat dál…\\" ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
55	{"blocks":[{"key":"eqcpf","text":"Co se vám nelíbilo:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":19,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"8jdk1","text":"„Poslala jsem vám dokumenty v několika e-mailech a ztratila jsem přehled, které dokumenty jste již přijali a které ještě chybí.\\" ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
19	{"blocks":[{"key":"3c3a3","text":"Potřebujete ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}},{"key":"7e9hv","text":"jinou pomoc?","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}},{"key":"8fso5","text":"221 221 221  ","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":13,"style":"BOLD"}],"entityRanges":[{"offset":0,"length":12,"key":0}],"data":{}}],"entityMap":{"0":{"type":"LINK","mutability":"MUTABLE","data":{"url":"tel:221221221","targetOption":"_self"}}}}
122	{"blocks":[{"key":"asafk","text":"Rel column text gouz hýr","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
83	{"blocks":[{"key":"3biv7","text":"Co se vám nelíbilo:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":19,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"3hjh9","text":"\\"Chybí mi školení přímo s likvidací nebo školení metodiky produktů, aby se šlo více do hloubky.\\"","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
20	{"blocks":[{"key":"fn6j2","text":"Škoda ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}},{"key":"7gb9q","text":"na autě","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}},{"key":"atoe","text":"270 270 777  ","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":13,"style":"BOLD"}],"entityRanges":[{"offset":0,"length":12,"key":0}],"data":{}}],"entityMap":{"0":{"type":"LINK","mutability":"MUTABLE","data":{"url":"tel:420270270777","targetOption":"_self"}}}}
51	{"blocks":[{"key":"csqh4","text":"Jak jsme to vyřešili:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":21,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"4dbhd","text":"Na základě zpětné vazby jsme v našem novém sjednavači přidali možnost nastavit frekvenci placení již při výběru rizik. Klient tak nyní najde možnost nastavení frekvence placení již v průběhu sjednávání pojištění, nikoli až na konci, jak to bylo dříve. ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
54	{"blocks":[{"key":"da93g","text":"Jak jsme to vyřešili:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":21,"style":"BOLD"},{"offset":0,"length":21,"style":"color-#000"}],"entityRanges":[],"data":{}},{"key":"aan7j","text":"Začali jsme pracovat na lepší cestě pro klienty, kteří chtějí nahlásit škodu. Máme za sebou vylepšení nahlášení škody z povinného ručení, postupně chceme proměnit webové hlášenky ke všem pojištěním. Naším cílem je, aby hlášení škody pro klienty bylo rychlé, jednoduché, spolehlivé a moderní. ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
123	{"blocks":[{"key":"5mdjf","text":"And another one","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
58	{"blocks":[{"key":"2pg7b","text":"Jak jsme to vyřešili:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":21,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"dgqv9","text":"Už nyní mohou klienti majetkového pojištění využít náš generátor výpovědí,  aby pro ně odchod  i odjinud nebyl tak bolestivý","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[{"offset":55,"length":19,"key":0}],"data":{}}],"entityMap":{"0":{"type":"LINK","mutability":"MUTABLE","data":{"url":"/online/generator-vypovedi","targetOption":"_blank"}}}}
84	{"blocks":[{"key":"92ojk","text":"Jak jsme to vyřešili: ","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":22,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"boet","text":"Vymysleli jsme Brunch s Directem, akci, která právě tyto požadavky řeší. Právě zde se můžete potkat mj. s těmi, kdo naše produkty vymýšlejí. Na poslední takové akci jsme přímo s naším produktovým specialistou probírali nové online pojištění podnikání. ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}},{"key":"99vpa","text":"V plánu máme také nová produktová videa. Stačí nám dát vědět a my vytvoříme prezentaci přímo pro vás na míru. ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
89	{"blocks":[{"key":"m2kt","text":"Jak jsme to vyřešili:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":21,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"901cu","text":"Už nyní máte možnost sjednat si havarijní pojištění na dobu určitou, tzn. třeba jen na léto.","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
50	{"blocks":[{"key":"9p2hv","text":"Jak jsme to vyřešili:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":21,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"5teif","text":"V rámci našeho nového sjednavače jsme připravili nejen jednoduchý přehled rozsahu asistencí, ale také ilustrativní příklady, které pomáhají klientům vybrat tu nejlepší asistenci odpovídající jejich potřebám. Současně jsme spustili také stránku věnovanou asistenčním službám, kterou naleznete tady.   ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[{"offset":292,"length":5,"key":0}],"data":{}}],"entityMap":{"0":{"type":"LINK","mutability":"MUTABLE","data":{"url":"https://www.direct.cz/auto/asistencni-sluzby","targetOption":"_blank"}}}}
56	{"blocks":[{"key":"2ppaa","text":"Jak jsme to vyřešili:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":21,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"2a0m0","text":"Pro naše klienty jsme vytvořili možnost, nahrát dokumenty do webového rozhraní, kde tak mají přehled, jaké dokumenty je třeba ještě dodat a co případně schází.","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
77	{"blocks":[{"key":"bn6ea","text":"Jak jsme to vyřešili:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":21,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"6rdjk","text":"Naši KAMové už mají k dispozici své kontaktní listy a rozesílají je mezi své obchodní partnery.  ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
86	{"blocks":[{"key":"a1ihv","text":"Co se vám nelíbilo:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":19,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"cqesb","text":"\\"Chybí mi informace o zaváděných novinkách.\\"","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
59	{"blocks":[{"key":"abbea","text":"Co se vám nelíbilo:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":19,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"5obp3","text":"„Chtěla bych ukončit smlouvu, kterou s Directem mám, ale nevím, jak to udělat. Hledám na webu, ale nemůžu najít…“ ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}},{"key":"chobq","text":"","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
87	{"blocks":[{"key":"arhig","text":"Co se vám nelíbilo:","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":19,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"41e6e","text":"\\"Přál bych si fixní spoluúčast klienta, ne jen procentní se spodním limitem. U aut spoluúčast ne procentem, ale částkou.\\"","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
61	{"blocks":[{"key":"eid89","text":"Co se vám nelíbilo: ","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":20,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"f56vu","text":"„Chybí mi možnost spravovat své pojištění na webu. Můžu buď zavolat na linku Directu nebo ťukat do telefonu, ale ani jedno mi nevyhovuje. Chci to mít hezky pohodlně na velké obrazovce.\\"","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
127	{"blocks":[{"key":"352r6","text":"Lorem ipsum dolor sit amet","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
62	{"blocks":[{"key":"a4dch","text":"Jak jsme to vyřešili: ","type":"unstyled","depth":0,"inlineStyleRanges":[{"offset":0,"length":22,"style":"BOLD"}],"entityRanges":[],"data":{}},{"key":"5vkp5","text":"Dali jsme dohromady klientskou zónu, tedy přístup ke správě vašeho pojištění přes web. Nyní máte tedy několik možností, jak své pojištění spravovat – na webu v klientské zóně, v appce nebo na telefonu s Direct operátorem. Vstup do klientské zóny najdete na webu Directu, vpravo nahoře. ","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[{"offset":257,"length":12,"key":0}],"data":{}}],"entityMap":{"0":{"type":"LINK","mutability":"MUTABLE","data":{"url":"https://www.direct.cz/","targetOption":"_blank"}}}}
128	{"blocks":[{"key":"1epu4","text":"Another one","type":"unstyled","depth":0,"inlineStyleRanges":[],"entityRanges":[],"data":{}}],"entityMap":{}}
